// Wounds use a stroked path instead of a filled silhouette; render them
// inline so we can pass stroke styling without polluting the shared map.
function WoundIcon({ className }) {
  return (
    <svg viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden="true">
      <path
        d="M120 100 L412 392 M412 100 L120 392"
        stroke="currentColor"
        strokeWidth="56"
        strokeLinecap="round"
        fill="none"
      />
    </svg>
  )
}

