export function TraitIcon({ trait, className }) {
  const d = TRAIT_ICON_PATHS[trait]
  if (!d) return null
  return (
    <svg viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden="true">
      <path fill="currentColor" d={d} />
    </svg>
  )
}

// Player affliction icons (single-fill silhouettes; the chips near the HP bar
// render these). One legible glyph per status.
//   blind    → eye struck through: you can't see the room
//   obscured → fog cloud:          you can't read card values
//   sealed   → padlock:            healing is shut off
//   bleeding → blood drop:         HP drains at each threshold
const AFFLICTION_ICON_PATHS = {
  blind: 'M256 168C150 168 80 256 80 256C80 256 150 344 256 344C362 344 432 256 432 256C432 256 362 168 256 168ZM40 132L472 344L456 380L24 168Z',
  obscured: 'M150 372C100 372 64 334 64 290C64 248 96 214 137 210C148 156 196 116 254 116C307 116 352 151 365 198C410 200 448 237 448 282C448 332 408 372 358 372Z',
  sealed: 'M152 240H360V416H152ZM196 240V186C196 153 223 126 256 126C289 126 316 153 316 186V240H284V186C284 170 271 158 256 158C241 158 228 170 228 186V240Z',
  bleeding: 'M256 88C256 88 152 236 152 322C152 380 198 424 256 424C314 424 360 380 360 322C360 236 256 88 256 88Z',
}

export function AfflictionIcon({ id, className }) {
  const d = AFFLICTION_ICON_PATHS[id]
  if (!d) return null
  return (
    <svg viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden="true">
      <path fill="currentColor" d={d} />
    </svg>
  )
}

export function SuitIcon({ suit, inscribed, boss, className }) {
  if (boss && BOSS_ICON_PATHS[boss]) {
    return <FilledIcon d={BOSS_ICON_PATHS[boss]} className={className} />
  }
  if (inscribed && INSCRIBED_ICON_PATHS[inscribed]) {
    return <FilledIcon d={INSCRIBED_ICON_PATHS[inscribed]} className={className} />
  }
  if (suit === WOUND) return <WoundIcon className={className} />
  // Synthetic suits used only by inscriptions; if a card has the suit
  // but no `inscribed` (defensive), fall back to the same silhouette.
  if (suit === KEY) return <FilledIcon d={INSCRIBED_ICON_PATHS.skeleton_key} className={className} />
  if (suit === MAP) return <FilledIcon d={INSCRIBED_ICON_PATHS.map} className={className} />
  if (suit === STONE) return <FilledIcon d={INSCRIBED_ICON_PATHS.whetstone} className={className} />
  if (suit === TORCH) return <FilledIcon d={INSCRIBED_ICON_PATHS.torch} className={className} />
  const d = SUIT_ICON_PATHS[suit]
  if (!d) return null
  // Hearts (potion-ball) mirrored so the flask reads better next to the rank.
  const flip = suit === HEART ? '-scale-x-100' : ''
  return (
    <svg viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" className={`${className} ${flip}`} aria-hidden="true">
      <path fill="currentColor" d={d} />
    </svg>
  )
}
